diff --git a/mail/base/content/about3Pane.js b/mail/base/content/about3Pane.js
index e516f784ec3..cb1618c91fc 100644
--- a/mail/base/content/about3Pane.js
+++ b/mail/base/content/about3Pane.js
@@ -2874,7 +2874,11 @@ var folderPane = {
       FolderUtils.getFolderIcon(gFolder);

     // Clean up any existing view wrapper. This will invalidate the thread tree.
-    gViewWrapper?.close();
+    // Rebuilding the selected folder is not leaving it, so we skip leave-folder
+    // behaviour.
+    gViewWrapper?.close({
+      leavingFolder: gViewWrapper?.displayedFolder != gFolder,
+    });

     if (gFolder.isServer) {
       document.title = gFolder.server.prettyName;
@@ -6322,7 +6326,7 @@ var folderListener = {
       // Clean up the display if the deleted folder was being displayed. At this
       // point, `DBViewWrapper._folderDeleted` has already cleaned up `gDBView`.
       gFolder = null;
-      gViewWrapper?.close(true);
+      gViewWrapper?.close({ leavingFolder: false });
       threadPaneHeader.onFolderSelected();
       threadPane._onSelect(); // Ensure no message is displayed.
     }
diff --git a/mail/base/content/aboutMessage.js b/mail/base/content/aboutMessage.js
index 3a9c2cc4b86..f8219c34650 100644
--- a/mail/base/content/aboutMessage.js
+++ b/mail/base/content/aboutMessage.js
@@ -194,7 +194,7 @@ function displayMessage(uri, viewWrapper) {
     // Don't clean up gViewWrapper if we're going to reuse it. If we're inside
     // about:3pane, close the view wrapper, but don't call `onLeavingFolder`,
     // because about:3pane will do that if we're actually leaving the folder.
-    gViewWrapper?.close(parent != top);
+    gViewWrapper?.close({ leavingFolder: parent == top });
     gViewWrapper = null;
   }

